shader_type canvas_item;

uniform float amount = 0.0;

void fragment() {
	vec2 uv = UV;
	uv.x -= amount;
	COLOR = texture(TEXTURE, uv);
}

shader_type canvas_item;

uniform float shift_x = 0.0;
uniform float shift_y = 0.0;

void fragment() {
	vec2 uv = UV;
	uv -= vec2(shift_x, shift_y);
	COLOR = texture(TEXTURE, uv);
}

shader_type canvas_item;

uniform float zoom = 1.0;

void fragment() {
	vec2 uv = UV * zoom;
	COLOR = texture(TEXTURE, uv);
}

shader_type canvas_item;

uniform sampler2D pic : repeat_enable;
uniform float zoom = 1.0;

void fragment() {
	vec2 uv = UV * zoom;
	COLOR = texture(pic, uv);
}

shader_type canvas_item;

uniform sampler2D pic : repeat_enable;

void fragment() {
	vec2 uv = UV;
	uv.x += TIME * 0.1;
	COLOR = texture(pic, uv);
}
